function claveValida(clave) {
  if (typeof clave !== "string") return false;
  return clave.length >= 8 &&
    clave.length <= 20 &&
    /\d/.test(clave);
}
console.assert(claveValida("clave1234") === true);
console.assert(claveValida("corta") === false);

